let cls = 0;
new PerformanceObserver((list) => {
  for (const shift of list.getEntries()) cls += shift.value;
}).observe({ type: "layout-shift", buffered: true });

addEventListener("load", () => {
  // Sent once, at load: no INP, no shifts after load
  navigator.sendBeacon("/vitals", JSON.stringify({ cls }));
});

import { onCLS, onINP, onLCP } from "web-vitals";

function send(metric) {
  const body = JSON.stringify({
    name: metric.name, // "LCP", "INP" or "CLS"
    value: metric.value,
    rating: metric.rating, // "good", "needs-improvement", "poor"
    id: metric.id,
    page: location.pathname,
  });
  navigator.sendBeacon("/vitals", body);
}

onLCP(send);
onINP(send);
onCLS(send);
